        fixes.sort(compareMessagesByFixRange).forEach(function(msg) {
            if (attemptFix(msg.fix)) {
                return fixesApplied.push(msg);
            }
            remainingMessages.push(msg);
        });
        fixedSourceCode += sourceCode.slice(Math.max(0, cursor));
