function getTemplateLanguageConstructs ( templateLanguage ) {
    var constructs;
    switch ( templateLanguage.toLowerCase() ) {
        case "handlebars":
            constructs = {
                startDelimiter: "{{",
                endDelimiter: "}}",
                if: "{{#if isActive}}",
                else: "{{else}}",
                endIf: "{{/if}}",
                loop: "{{#each looped as |value index|}}",
                endLoop: "{{/each}}",
                partial: '{{> userMessage tagName="h2" }}'
            };
            break;
        case "ejs":
            constructs = {
                startDelimiter: "<%= ",
                endDelimiter: " %>",
                if: "<% if (isActive) { %>",
                else: "<% } else { %>",
                endIf: "<% } %>",
                loop: "<% looped.forEach(function(item) { %>",
                endLoop: "<% }); %>",
                partial: "<%- include('user/show', {user: user}); %>"
            };
            break;
        case "es6":
            constructs = {
                startDelimiter: "${",
                endDelimiter: "}",
                if: "",
                else: "",
                endIf: "",
                loop: "",
                endLoop: "",
                partial: ""
            };
            break;
        default:
            throw new Error( 'Unsupported template language "' + templateLanguage + '"' );
    }
    return constructs;
}

