    landmarks[filePath] = true
    slugs.reset()
    visit(ast, mark)
    space[referenceId] = references
    space[landmarkId] = landmarks
    function mark(node) {
      var data = node.data || {}
      var props = data.hProperties || {}
      var id = props.name || props.id || data.id
      if (!id && node.type === 'heading') {
