function run(context, fn, finish, args) {
	if (typeof context == 'function') {  
		args = finish;
		finish = fn;
		fn = context;
		context = this;
	}
	if (isPromise(fn)) {  
		fn
			.then(function(value) {
				finish.apply(context, [null, value]);
			})
			.catch(function(err) {
				finish.call(context, err || 'An error occured');
			});
	} else if (hasCallback(fn)) {  
		var result = fn.apply(context, args ? [finish].concat(args) : [finish]);
		if (isPromise(result)) {
			result
				.then(function(value) {  
					finish.apply(context, [null, value]);
				})
				.catch(function(err) {
					finish.call(context, err || 'An error occured');
				});
		}
	} else {  
		var result;
		try {
			result = fn.apply(context, args || []);  
		} catch (e) {
			finish.call(context, e);
		}
		if (isPromise(result)) {  
			result
				.then(function(value) {  
					finish.apply(context, [null, value]);
				})
				.catch(function(err) {
					finish.call(context, err || 'An error occured');
				});
		} else {  
			finish.apply(context, [null, result]);
		}
	}
}

