    var gain = options.gain || defaultOptions.gain || 0.4
    var vco = ctx.createOscillator()
    vco.type = vcoType
    vco.frequency.value = freq
    var vca = ctx.createGain()
    vca.gain.value = gain
    vco.connect(vca)
    vca.connect(destination)
    vco.start(time)
    if (duration > 0) vco.stop(time + duration)
