        'rebuilding'
      )
      break
    }
    case 'built':
    case 'sync': {
      clearOutdatedErrors()
      if (obj.hash) {
        handleAvailableHash(obj.hash)
      }
      if (obj.warnings.length > 0) {
        handleWarnings(obj.warnings)
      }
      if (obj.errors.length > 0) {
