          hadRuntimeError = true
        }
        handleErrors(obj.errors)
        break
      }
      handleSuccess()
      break
    }
    default: {
      if (customHmrEventHandler) {
        customHmrEventHandler(obj)
        break
      }
      break
    }
  }
}

