      let previousElement = records[pivotIndex - 1].record
      if (comparator(previousElement, record) <= 0) {
        return pivotIndex
      }

      top = pivotIndex - 1
    } else {
      bottom = pivotIndex + 1
    }
  }

  return records.length
}

