            const fullName = oldBranch.getFullName();
            const newBranch = repoState.getBranch(fullName);
            if (newBranch === null || newBranch.getSha() !== oldBranch.getSha()) {
                return updateWorkingState(repoState, oldBranch, null);
            } else {
                return repoState;
            }
        }, repoState);
    });
}

