      if (typeof str !== 'string') {
        throw new TypeError('repeat-string expects a string.');
      }
      if (num === 1) return str;
      if (num === 2) return str + str;
      var max = str.length * num;
      if (cache !== str || typeof cache === 'undefined') {
        cache = str;
        res = '';
      }
      while (max > res.length && num > 0) {
        if (num & 1) {
          res += str;
